/**
 * Unit tests for the UserRoleAssignamentRolesRoleAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserRoleAssignamentRolesRoleAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getRole returns null on a freshly created holder.
         */
        public function testRoleNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithUserRoleAssignamentRolesRoleAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isRoleAssigned());
            $this->assertNull($holder->getRole());
        }
}
